// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {X_WALLET, Log} from "../src/X_WALLET.sol";

contract InvMutTest is Test {
    X_WALLET c;
    function setUp() public { c = new X_WALLET(address(new Log())); }

    function testFuzz_property(address actor, uint256 first, uint256 second) public {
        vm.assume(actor != address(0));
        first = bound(first, 0, 10 ether);
        second = bound(second, 0, 10 ether);
        vm.deal(actor, first + second);
        vm.prank(actor);
        c.Put{value: first}(0);
        vm.prank(actor);
        c.Put{value: second}(0);
        (, uint256 bal) = c.Acc(actor);
        assertTrue(bal == first + second);
    }
}
